<script setup lang="ts">
import {t,locale} from '../i18n'

import {ref} from 'vue'
import {Download,WifiOff,RefreshCw,Trash2,Check,AlertCircle} from 'lucide-vue-next'
import {offlineEnabled,pendingWrites,offlineMessage,offlineSavedAt,cachedPictures,networkOnline,syncing,enableOffline,clearOffline,syncOffline,resolveWrite,exportDrafts} from '../offline'
import {installPrompt,installApp,pwaAvailable,updateWorker,applyUpdate} from '../pwa'
import {useAlbum} from '../store'
const album=useAlbum(),busy=ref(false),error=ref(''),consent=ref(false),confirmClear=ref(false),confirmLocal=ref('')
async function run(action:()=>Promise<unknown>){busy.value=true;error.value='';try{await action();await album.refresh()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function resolve(id:string,action:'server'|'local'){await run(()=>resolveWrite(id,action));confirmLocal.value=''}
</script>
<template><section class="settings-card glass device-settings"><span class="stat-icon blue"><WifiOff :size="23"/></span><span class="eyebrow">TAKE OUR STORY WITH YOU</span><h2>{{t('安装与离线使用')}}</h2><p class="muted">{{t('把足迹添加到桌面；保存本机副本后，断网也能整理回忆和共同清单。')}}</p><button v-if="installPrompt" class="primary" @click="installApp"><Download :size="16"/>{{t('安装足迹')}}</button><p v-else class="small muted">{{pwaAvailable?t('可在浏览器菜单中选择“安装应用”或“添加到主屏幕”。'):t('桌面安装与离线页面需要使用 HTTPS 或本机 localhost 地址。')}}</p><button v-if="updateWorker" class="secondary" @click="applyUpdate">{{t('新版本已准备好，刷新应用')}}</button><hr><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="offlineMessage" class="small muted" role="status">{{offlineMessage}}</p><template v-if="!offlineEnabled"><label class="offline-consent"><input v-model="consent" type="checkbox">{{t('我愿意在此设备保留回忆、清单和缩略图副本。能使用此浏览器的人也能访问这些内容。')}}</label><button class="primary" :disabled="!consent||busy||!networkOnline" @click="run(enableOffline)"><Download :size="16"/>{{busy?t('正在准备…'):t('保存离线副本')}}</button></template><template v-else><p class="small muted"><Check :size="14"/>{{t('已保留本机副本 · {0} 张缩略图', [cachedPictures])}}<br>{{t('最近更新：{0}', [new Date(offlineSavedAt).toLocaleString()])}}</p><button class="secondary" :disabled="busy||!networkOnline||pendingWrites.length>0" @click="run(enableOffline)"><RefreshCw :size="14"/>{{t('更新离线副本')}}</button></template><p class="small muted">{{t('离线支持修改已有回忆的文字、分类、坐标、封面和照片顺序，以及共同清单。上传、删除、配对和原图下载需要联网；本机最多保留 200 张缩略图，总计不超过 40MB。退出登录会清除本机副本。')}}</p><div v-if="pendingWrites.length" class="offline-queue"><h3>{{t('待同步修改 · {0}', [pendingWrites.length])}}</h3><button class="secondary" :disabled="busy||syncing||!networkOnline" @click="run(syncOffline)">{{syncing?t('正在同步…'):t('立即同步')}}</button><button class="text-button" @click="run(exportDrafts)">{{t('导出修改草稿')}}</button><article v-for="item in pendingWrites" :key="item.id"><strong>{{item.path.startsWith('/memories/')?t('回忆修改'):t('共同清单修改')}}</strong><span>{{item.status==='pending'?t('等待联网同步'):item.status==='conflict'?t('与另一半的更新冲突'):t('需要处理')}}</span><p v-if="item.message" class="small error">{{item.message}}</p><template v-if="item.status!=='pending'"><button class="secondary" :disabled="busy||!networkOnline" @click="resolve(item.id,'server')">{{t('采用服务端内容')}}</button><button v-if="confirmLocal!==item.id" class="text-button" :disabled="busy||!networkOnline" @click="confirmLocal=item.id">{{t('使用我的离线修改')}}</button><template v-else><p class="small muted">{{t('这会将当前服务端内容替换为你的离线版本。请确认已与另一半核对。')}}</p><button class="secondary danger" :disabled="busy" @click="resolve(item.id,'local')">{{t('确认使用我的修改')}}</button><button class="text-button" @click="confirmLocal=''">{{t('取消')}}</button></template></template></article></div><div class="offline-clear"><button v-if="!confirmClear" class="text-button danger" @click="confirmClear=true"><Trash2 :size="14"/>{{t('清除本机副本')}}</button><template v-else><p class="small muted">{{t('将移除本机副本及尚未同步的草稿，服务端内容不受影响。需要的草稿请先导出。')}}</p><button class="text-button" @click="run(exportDrafts)">{{t('导出草稿')}}</button><button class="secondary danger" :disabled="busy" @click="run(clearOffline);confirmClear=false">{{t('确认清除')}}</button><button class="text-button" @click="confirmClear=false">{{t('取消')}}</button></template></div></section></template>
